"""Giant evil moth and giant evil bat (your sprite sets). All frames face left.
moth: fly (wings beat), attack (gathers a sphere of purple magic and flings it), death (wings shudder and it collapses)
bat:  fly (wing beat loop), attack (a red sonic screech), death (wings fold and it drops)"""
import base64
import zlib
import pygame

NIGHT = {
  'moth': {'size': (96, 81), 'anchor': (55, 40), 'muzzle': (-27, -5), 'bottom': (74, 74, 73, 72, 71, 69, 67, 67, 67, 67, 68, 70, 74, 75, 77, 76, 80),
           'frames': {'fly': (17, ''), 'attack': (17, ''), 'death': (17, '')}},
  'bat': {'size': (86, 79), 'anchor': (47, 35), 'muzzle': (-18, -2), 'bottom': (65, 65, 64, 64, 64, 65, 65, 65, 65, 65, 65, 64, 67, 67, 67, 67, 67),
           'frames': {'fly': (17, ''), 'attack': (17, ''), 'death': (17, '')}},
}
_RAW, _CACHE = {}, {}


def night_count(kind, anim):
  return NIGHT[kind]['frames'][anim][0]


def night_frame(kind, anim, i, scale=1.0):
  """(surface, anchor_x, anchor_y): the anchor is the creature's body centre inside the surface."""
  info = NIGHT[kind]
  n, data = info['frames'][anim]
  i = int(i) % n
  k = (kind, anim, i, scale)
  hit = _CACHE.get(k)
  if hit is None:
    w, h = info['size']
    raw = _RAW.get((kind, anim))
    if raw is None:
      raw = _RAW[(kind, anim)] = zlib.decompress(base64.b64decode(data))
    m = w * h * 4
    s = pygame.image.frombuffer(raw[i * m:(i + 1) * m], (w, h), 'RGBA').copy()
    if scale != 1.0:
      s = pygame.transform.scale(s, (int(w * scale), int(h * scale)))
    ax, ay = info['anchor']
    hit = _CACHE[k] = (s, int(ax * scale), int(ay * scale))
  return hit


def night_muzzle(kind, scale):
  mx, my = NIGHT[kind]['muzzle']
  return mx * scale, my * scale


def night_bottom(kind, i, scale):
  """how far below the anchor the lowest pixel of death frame i sits"""
  info = NIGHT[kind]
  b = info['bottom'][max(0, min(len(info['bottom']) - 1, int(i)))]
  return (b - info['anchor'][1]) * scale
